/**
 * The real sites, from capture.mjs: full-page captures down to a cut, and
 * the boxes of the sections above it.
 *
 *   cedar  Cedar & Stone, public/landscaping.html — a fictional business's
 *          concept site, hand-built by us. In the film's build beat,
 *          labelled "a fictional example".
 *   ark    Allergy Rescue Kit, allergyrescuekit.com — a real client, live.
 *   andys  Andy's Auto Shop, andysauto.org — a demo business on a real
 *          domain, generated by the platform. Only in Ad_AllWeNeed.
 *
 * Assemble: the page's own sections arrive one by one — the header slides
 * down, the hero snaps in, then a section every `gap` seconds with a whoosh.
 * Only sections above the capture's cut exist here.
 */
import React from 'react';
import { Img, interpolate } from 'remotion';
import cedarImg from '../../assets/footage/cedar-1440.jpg';
import cedarJson from '../../assets/footage/cedar-sections.json';
import arkImg from '../../assets/footage/ark-1440.jpg';
import arkJson from '../../assets/footage/ark-sections.json';
import andysImg from '../../assets/footage/andys-1440.jpg';
import andysJson from '../../assets/footage/andys-sections.json';
import { useCurrentFrame } from 'remotion';
import { clamp, ease, ramp, useSeconds } from '../kit.tsx';
import { springAt } from '../motion/Stage.tsx';
import { FPS } from '../script.ts';
import type { Box } from '../sizes.ts';
import type { Sfx } from './types.ts';

type Section = { id: string; y: number; height: number };
export type Site = { src: string; url: string; w: number; h: number; sections: Section[] };
const site = (src: string, url: string, j: { 1440: { sections: Section[]; stopAt: number } }): Site =>
  ({ src, url, w: 1440, h: j[1440].stopAt, sections: j[1440].sections });

export const SITES = {
  cedar: site(cedarImg, 'cedarandstone.example', cedarJson),
  ark: site(arkImg, 'allergyrescuekit.com', arkJson),
  andys: site(andysImg, 'andysauto.org', andysJson),
};

/** When each section arrives, seconds after the assembly starts. */
export const arrivals = (s: Site, gap: number) => s.sections.map((_, i) => (i === 0 ? 0 : i === 1 ? 0.1 : 0.2 + (i - 1) * gap));

export function assembleSfx(s: Site, from: number, gap: number): Sfx[] {
  return arrivals(s, gap).map((a, i) => ({ t: from + a, kind: 'whoosh', gain: i === 0 ? 0.5 : 0.7 }));
}

/** A frame for the whole page in `stage`: as tall as the stage, as wide as
 *  the page's shape makes it. */
export function overviewBox(s: Site, stage: Box, bar: number): Box {
  const ch = stage.h - bar - 2;
  const w = (ch * s.w) / s.h + 4;
  return { x: stage.x + (stage.w - w) / 2, y: stage.y, w, h: stage.h };
}

/**
 * The page in `box` (a frame's content box), sections arriving.
 *   mode 'overview': the whole page is in the box (the box is page-shaped);
 *     once the last section lands the camera pushes in towards the hero.
 *   mode 'scroll': the page fills the box's width; the camera pushes down
 *     the page behind the sections as they arrive, ending on the last.
 */
export const Assemble: React.FC<{ site: Site; box: Box; from: number; gap: number; end: number; mode: 'overview' | 'scroll' }> = ({ site: S, box, from, gap, end, mode }) => {
  const t = useSeconds() - from;
  const s = box.w / S.w;
  const arr = arrivals(S, gap);
  const settled = arr[arr.length - 1] + 0.3;
  const dur = end - from;
  const push = mode === 'overview' ? interpolate(t, [settled, Math.max(settled + 0.5, dur)], [1, 1.06], clamp) : 1;
  // 'scroll': the camera follows the newest section down — never ahead of
  // it, so there is never blank page below the last one in.
  const visible = box.h / s;
  const scrollY = mode !== 'scroll' ? 0 : S.sections.reduce((y, sec, i) => {
    const want = Math.max(0, Math.min(S.h - visible, sec.y + sec.height - visible));
    return interpolate(t, [arr[i] + 0.05, arr[i] + 0.45], [y, Math.max(y, want)], { ...clamp, easing: ease });
  }, 0);
  return (
    <div style={{ position: 'absolute', left: box.x, top: box.y, width: box.w, height: box.h, overflow: 'hidden', background: '#fff' }}>
      <div style={{ position: 'absolute', inset: 0, transform: `scale(${push})`, transformOrigin: '50% 12%' }}>
        {S.sections.map((sec, i) => {
          const a = arr[i];
          if (t < a) return null;
          const p = ramp(t, a, i === 1 ? 0.16 : 0.26);
          const dy = sec.id === 'header' ? -(1 - p) * sec.height : sec.id === 'hero' ? 0 : (1 - p) * 80;
          const sc = sec.id === 'hero' ? 0.96 + 0.04 * p : 1;
          return (
            <div
              key={sec.id}
              style={{
                position: 'absolute', left: 0, top: (sec.y - scrollY) * s, width: box.w, height: sec.height * s,
                overflow: 'hidden', opacity: sec.id === 'header' ? 1 : p,
                transform: `translateY(${dy * s}px) scale(${sc})`, zIndex: sec.id === 'header' ? 2 : 1,
              }}
            >
              <Img src={S.src} style={{ position: 'absolute', left: 0, top: -sec.y * s, width: S.w * s, height: S.h * s, maxWidth: 'none' }} />
            </div>
          );
        })}
      </div>
    </div>
  );
};

/** The page's top, scrolling slowly — a desktop beside a phone. */
export const Desktop: React.FC<{ site: Site; box: Box; from?: number; dur: number; travel?: number }> = ({ site: S, box, from = 0, dur, travel = 260 }) => {
  const t = useSeconds() - from;
  const s = box.w / S.w;
  const y = interpolate(t, [0, dur], [0, travel], { ...clamp, easing: ease });
  return (
    <div style={{ position: 'absolute', left: box.x, top: box.y, width: box.w, height: box.h, overflow: 'hidden' }}>
      <Img src={S.src} style={{ position: 'absolute', left: 0, top: -y * s, width: S.w * s, height: S.h * s, maxWidth: 'none' }} />
    </div>
  );
};

/**
 * V2.1 §5: assembly from depth. Each section starts at translateZ(−900px),
 * 30% opacity, 12px blur, turned ±3°, and springs into place, `step` apart.
 * The box is the device's content area (its own coordinates, 0,0 top-left).
 *   'scroll'   the page fills the width; once every section has landed the
 *              camera pushes down the page to the end of the beat.
 *   'overview' the whole page is in the (page-shaped) box.
 */
export const AssembleDepth: React.FC<{ site: Site; w: number; h: number; from: number; step: number; end: number; mode: 'overview' | 'scroll' }> = ({ site: S, w, h, from, step, end, mode }) => {
  const frame = useCurrentFrame();
  const t = frame / FPS - from;
  const s = w / S.w;
  const landed = depthLanded(S, step);
  const maxScroll = Math.max(0, S.h - h / s);
  const scrollY = mode === 'scroll' ? interpolate(t, [landed + 0.1, end - from - 0.1], [0, maxScroll], { ...clamp, easing: ease }) : 0;
  return (
    <div style={{ position: 'absolute', left: 0, top: 0, width: w, height: h, overflow: 'hidden', perspective: 1400, perspectiveOrigin: '50% 30%' }}>
      {S.sections.map((sec, i) => {
        const at = from + i * step;
        if (frame < Math.round(at * FPS)) return null;
        const p = springAt(frame, at);
        const q = Math.min(1, p);
        const turn = (i % 2 ? -3 : 3) * (1 - p);
        return (
          <div
            key={sec.id}
            style={{
              position: 'absolute', left: 0, top: (sec.y - scrollY) * s, width: w, height: sec.height * s, overflow: 'hidden',
              transform: `translateZ(${-900 * (1 - p)}px) rotateZ(${turn}deg)`,
              opacity: 0.3 + 0.7 * q, filter: q < 0.999 ? `blur(${12 * (1 - q)}px)` : undefined, zIndex: S.sections.length - i,
            }}
          >
            <Img src={S.src} style={{ position: 'absolute', left: 0, top: -sec.y * s, width: S.w * s, height: S.h * s, maxWidth: 'none' }} />
          </div>
        );
      })}
    </div>
  );
};

/** Seconds after the first section starts until the last has landed. */
export const depthLanded = (S: Site, step: number) => (S.sections.length - 1) * step + 0.6;
